import pathlib,json,hashlib,re,decimal,struct,time,os

def canonical(value):return json.dumps(value,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode('utf-8')
def digest(value):return hashlib.sha256(canonical(value)).hexdigest()
def rows(conn,sql,args=()):
    with conn.cursor()as cursor:cursor.execute(sql,args);return cursor.fetchall()
def integer(value,low,high):return type(value)is int and low<=value<=high
def text(value,limit):
    if not isinstance(value,str)or not 1<=len(value)<=limit:raise ValueError('bounded text required')
    value.encode('utf-8')
def commit_positions(raw):
    if raw[:4]!=b'\xfebin':raise ValueError('binlog magic')
    offset=4;commits=[];first=True
    while offset<len(raw):
        if len(raw)-offset<19:raise ValueError('truncated event header')
        _,kind,_,size,end,_=struct.unpack_from('<IBIIIH',raw,offset)
        if size<19 or offset+size>len(raw):raise ValueError('truncated event')
        if first:
            if kind!=15 or size<76 or struct.unpack_from('<H',raw,offset+19)[0]!=4 or raw[offset+75]!=19:raise ValueError('uncompressed v4 nineteen-byte header format required')
            first=False
        if kind==16:
            if end!=offset+size:raise ValueError('native XID byte coordinate')
            commits.append(end)
        offset+=size
    return commits

def validate_materials(material_root,plan):
    fields={'schema','schema_name','source_uuid','target_uuid','log_file','start_position','stop_position','backup_sha256','binlog_sha256','confirmations_sha256','approved_state','incident_us'}
    if not isinstance(plan,dict)or set(plan)!=fields or type(plan['schema'])is not int or plan['schema']!=1 or plan['schema_name']!='training':raise ValueError('exact approved plan schema')
    for field in('source_uuid','target_uuid'):
        if not isinstance(plan[field],str)or not re.fullmatch('[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}',plan[field]):raise ValueError('UUID scope')
    if plan['source_uuid']==plan['target_uuid']:raise ValueError('source cannot be the restore target')
    if not isinstance(plan['log_file'],str)or not re.fullmatch(r'[A-Za-z0-9_-]+\.[0-9]{6}',plan['log_file']):raise ValueError('single approved binlog basename')
    if not integer(plan['start_position'],4,4*1048576)or not integer(plan['stop_position'],4,4*1048576)or plan['stop_position']<=plan['start_position']or not integer(plan['incident_us'],0,2**63-1):raise ValueError('cutoff coordinates/time')
    directory=pathlib.Path(material_root).resolve();data={}
    for name,field,budget in[('backup.sql','backup_sha256',2*1048576),('source.bin','binlog_sha256',4*1048576),('confirmations.json','confirmations_sha256',1048576)]:
        if not isinstance(plan[field],str)or not re.fullmatch('[0-9a-f]{64}',plan[field]):raise ValueError('approved artifact digest')
        path=directory/name
        if path.is_symlink():raise ValueError('material child symlink')
        value=path.read_bytes()
        if not 1<=len(value)<=budget or hashlib.sha256(value).hexdigest()!=plan[field]:raise ValueError('material size/digest')
        data[name]=value
    backup=data['backup.sql']
    source=re.findall(rb'^-- OPSFORGE_SOURCE_UUID=([0-9a-f-]{36})$',backup,re.M)
    coordinates=re.findall(rb"CHANGE REPLICATION SOURCE TO SOURCE_LOG_FILE='([^']+)', SOURCE_LOG_POS=([0-9]+)",backup)
    if source!=[plan['source_uuid'].encode()]or coordinates!=[(plan['log_file'].encode(),str(plan['start_position']).encode())]:raise ValueError('backup source/capture coordinate differs')
    commits=commit_positions(data['source.bin'])
    if plan['start_position']not in commits or plan['stop_position']not in commits:raise ValueError('approved start/stop must be native XID-end commit boundaries')
    confirmations=json.loads(data['confirmations.json'])
    if not isinstance(confirmations,list)or not 1<=len(confirmations)<=1000:raise ValueError('confirmation budget')
    previous_seq=0;previous_time=-1
    for item in confirmations:
        if not isinstance(item,dict)or set(item)!={'seq','ack_us'}or not integer(item['seq'],1,2**31-1)or not integer(item['ack_us'],0,plan['incident_us'])or item['seq']<=previous_seq or item['ack_us']<=previous_time:raise ValueError('ordered confirmed transactions')
        previous_seq=item['seq'];previous_time=item['ack_us']
    approved=plan['approved_state']
    if not isinstance(approved,dict)or set(approved)!={'customers','orders','journal'}:raise ValueError('approved business state')
    for name in approved:
        if not isinstance(approved[name],list)or not 1<=len(approved[name])<=1000:raise ValueError('approved row budget')
    ids=set();last=0
    for row in approved['customers']:
        if not isinstance(row,list)or len(row)!=2 or not integer(row[0],1,2**31-1)or row[0]<=last:raise ValueError('approved customer rows')
        text(row[1],120);ids.add(row[0]);last=row[0]
    last=0;request_keys=set()
    for row in approved['orders']:
        if not isinstance(row,list)or len(row)!=5 or not integer(row[0],1,2**31-1)or row[0]<=last or not integer(row[1],1,2**31-1)or row[1]not in ids:raise ValueError('approved order identity/FK')
        if not isinstance(row[2],str)or not re.fullmatch('[a-z0-9_-]{1,32}',row[2])or row[2]in request_keys:raise ValueError('order request identity')
        if not isinstance(row[3],str)or not re.fullmatch(r'(0|[1-9][0-9]{0,9})\.[0-9]{2}',row[3]):raise ValueError('exact nonnegative amount')
        text(row[4],512);request_keys.add(row[2]);last=row[0]
    last=0;journal_keys=set()
    for row in approved['journal']:
        if not isinstance(row,list)or len(row)!=2 or not integer(row[0],1,2**31-1)or row[0]<=last or not isinstance(row[1],str)or not re.fullmatch('[a-z0-9_-]{1,32}',row[1])or row[1]in journal_keys:raise ValueError('approved journal')
        journal_keys.add(row[1]);last=row[0]
    if[row[0]for row in approved['journal']]!=[item['seq']for item in confirmations[:len(approved['journal'])]]:raise ValueError('restored journal must be a confirmed prefix')
    return{'data':data,'confirmations':confirmations,'plan_sha256':digest(plan)}

def snapshot(target):
    tables=rows(target,"SELECT TABLE_NAME,TABLE_TYPE FROM information_schema.tables WHERE TABLE_SCHEMA='training' ORDER BY TABLE_NAME")
    if tables!=(('customers','BASE TABLE'),('journal','BASE TABLE'),('orders','BASE TABLE')):raise ValueError('restored table set differs')
    return{'customers':[list(row)for row in rows(target,'SELECT id,name FROM training.customers ORDER BY id')],
           'orders':[[a,b,c,str(d),e]for a,b,c,d,e in rows(target,'SELECT id,customer_id,request_key,amount,note FROM training.orders ORDER BY id')],
           'journal':[list(row)for row in rows(target,'SELECT seq,request_key FROM training.journal ORDER BY seq')]}

def publish(path,value):
    data=canonical(value)+b'\n';temporary=path.with_name(path.name+'.tmp-'+str(os.getpid()))
    if path.is_symlink():raise ValueError('report child symlink')
    try:
        with temporary.open('xb')as stream:stream.write(data);stream.flush();os.fsync(stream.fileno())
        os.link(temporary,path,follow_symlinks=False)
    finally:temporary.unlink(missing_ok=True)

def restore(target,material_root,plan,clients,report_root,checkpoint=None):
    started=time.monotonic_ns();verified=validate_materials(material_root,plan)
    if not target.get_autocommit()or target.server_status&1:raise ValueError('clean borrowed target connection')
    if rows(target,'SELECT @@server_uuid')[0][0]!=plan['target_uuid']:raise ValueError('approved target UUID mismatch')
    for sql in["SELECT COUNT(*) FROM information_schema.tables WHERE TABLE_SCHEMA='training'","SELECT COUNT(*) FROM information_schema.routines WHERE ROUTINE_SCHEMA='training'","SELECT COUNT(*) FROM information_schema.events WHERE EVENT_SCHEMA='training'"]:
        if rows(target,sql)!=((0,),):raise ValueError('target training namespace must be empty; preserve existing or partial data')
    root=pathlib.Path(report_root).resolve();directory=root/plan['target_uuid']
    if directory.is_symlink()or directory.exists():raise ValueError('one attempt per target UUID; preserve old evidence')
    binlog=pathlib.Path(material_root).resolve()/'source.bin'
    clients.run('mysqlbinlog',['--verify-binlog-checksum',str(binlog)])
    replay=clients.run('mysqlbinlog',['--verify-binlog-checksum','--start-position='+str(plan['start_position']),'--stop-position='+str(plan['stop_position']),str(binlog)])
    root.mkdir(parents=True,exist_ok=True);directory.mkdir()
    publish(directory/'attempt.json',{'schema':1,'target_uuid':plan['target_uuid'],'plan_sha256':verified['plan_sha256'],'replay_sha256':hashlib.sha256(replay).hexdigest()})
    stage='base'
    try:
        clients.run('mysql',clients.target_args(target),verified['data']['backup.sql'])
        if checkpoint is not None:checkpoint('base')
        stage='replay';clients.run('mysql',clients.target_args(target),replay)
        if checkpoint is not None:checkpoint('replay')
        stage='business_check';actual=snapshot(target)
        if actual!=plan['approved_state']:raise ValueError('actual complete approved business state differs')
        restored=[row[0]for row in actual['journal']];confirmed=verified['confirmations'];seen=set(restored);lost=[item['seq']for item in confirmed if item['seq']not in seen]
        last_ack=next(item['ack_us']for item in confirmed if item['seq']==restored[-1])
        result={'schema':1,'target_uuid':plan['target_uuid'],'source_uuid':plan['source_uuid'],'plan_sha256':verified['plan_sha256'],'log_file':plan['log_file'],'start_position':plan['start_position'],'stop_position':plan['stop_position'],'business_verified':True,'state_sha256':digest(actual),'restored_sequences':restored,'lost_confirmed_sequences':lost,'rpo_us':plan['incident_us']-last_ack,'rto_ns':time.monotonic_ns()-started}
        stage='success_report';publish(directory/'report.json',result)
        return result
    except Exception as error:
        publish(directory/'failure.json',{'schema':1,'target_uuid':plan['target_uuid'],'plan_sha256':verified['plan_sha256'],'stage':stage,'error_type':type(error).__name__})
        raise

